def optimize_adagrad(grads, weights, cache, lr=0.01):
    for i in range(len(weights)):
        cache[i] += grads[i] ** 2
        weights[i] -= (lr / (np.sqrt(cache[i]) + 1e-8)) * grads[i]
    return weights, cache

def rmsprop(params, grads, cache, lr=0.01, decay=0.9):
    for p in range(len(params)):
        cache[p] = decay * cache[p] + (1 - decay) * (grads[p] ** 2)
        params[p] -= (lr / (np.sqrt(cache[p]) + 1e-8)) * grads[p]
    return params, cache

def clip_gradients(parameters, max_norm):
    total_norm = torch.sum(torch.stack([torch.sum(p.grad ** 2) for p in parameters if p.grad is not None])) ** 0.5
    clip_coef = max_norm / (total_norm + 1e-6)
    if clip_coef < 1:
        for p in parameters:
            if p.grad is not None:
                p.grad.data.mul_(clip_coef)

