class DAE(nn.Module):
    def __init__(self):
        super().__init__()
        self.enc = nn.Linear(5, 2)
        self.dec = nn.Linear(2, 5)
    def forward(self, x):
        noise = torch.randn_like(x) * 0.1
        noisy_x = x + noise
        h = torch.relu(self.enc(noisy_x))
        return self.dec(h)

