def manual_group_norm(x, num_groups, eps=1e-5):
    N, C, H, W = x.shape
    assert C % num_groups == 0
    # Reshape to separate groups
    x_reshaped = x.view(N, num_groups, C // num_groups, H, W)
    # Compute mean and variance along group channels, H, and W
    mean = x_reshaped.mean(dim=[2, 3, 4], keepdim=True)
    var = x_reshaped.var(dim=[2, 3, 4], unbiased=False, keepdim=True)
    x_normalized = (x_reshaped - mean) / torch.sqrt(var + eps)
    return x_normalized.view(N, C, H, W)

