import numpy as np

def softmax(preferences):
    exp_prefs = np.exp(preferences - np.max(preferences))
    return exp_prefs / np.sum(exp_prefs)

def policy_gradient_bandit(steps, num_arms, true_rewards, alpha=0.1):
    preferences = np.zeros(num_arms)
    average_reward = 0

    for t in range(1, steps + 1):
        probs = softmax(preferences)
        action = np.random.choice(num_arms, p=probs)
        reward = np.random.normal(true_rewards[action], 1.0)

        average_reward += (reward - average_reward) / t

        # Update preferences
        for a in range(num_arms):
            if a == action:
                preferences[a] += alpha * (reward - average_reward) * (1 - probs[a])
            else:
                preferences[a] -= alpha * (reward - average_reward) * probs[a]

    return softmax(preferences)

print(policy_gradient_bandit(2000, 3, [0.1, 0.8, 0.4]))

