def extract_policy(V, P, R, gamma, n_states, n_actions):
    policy = np.zeros(n_states, dtype=int)
    for s in range(n_states):
        q_vals = [sum(P[s, a, s_prime] * (R[s, a, s_prime] + gamma * V[s_prime]) for s_prime in range(n_states)) for a in range(n_actions)]
        policy[s] = np.argmax(q_vals)
    return policy

def improve_policy(V, P, R, gamma, n_states, n_actions):
    policy = np.zeros(n_states, dtype=int)
    for s in range(n_states):
        q_vals = [sum(P[s, a, s_prime] * (R[s, a, s_prime] + gamma * V[s_prime]) for s_prime in range(n_states)) for a in range(n_actions)]
        policy[s] = np.argmax(q_vals)
    return policy

def compute_lstd(Phi, Phi_next, rewards, gamma):
    A = Phi.T @ (Phi - gamma * Phi_next)
    b = Phi.T @ rewards
    return np.linalg.solve(A + 1e-4 * np.eye(A.shape[0]), b)

def compute_fqi_targets(rewards, next_q_values, gamma):
    max_next_q = np.max(next_q_values, axis=1, keepdims=True)
    return rewards + gamma * max_next_q

def dueling_aggregation(v, a):
