import numpy as np
def compute_feature_expectations(trajectories, gamma, features):
    fe = np.zeros(features.shape[1])
    for traj in trajectories:
        for t, state in enumerate(traj):
            fe += (gamma ** t) * features[state]
    return fe / len(trajectories)

